    @Test
    void writesThroughTheRealDatabase() {
        Author authorRow = authorRepository.save(new Author(1L, "sample"));
        Optional<Note> answered = operation.execute(new PostNoteCommand.Input("sample", "sample"));

        // `returning` answers with the row the statement wrote, so an empty
        // answer here means it matched none -- which is the failure worth
        // catching.
        assertThat(answered).isPresent();
        assertThat(answered.orElseThrow().authorId()).isEqualTo(authorRow.id());
    }

    @Test
    void answersEmptyWhenNoParentMatches() {
        assertThat(operation.execute(new PostNoteCommand.Input("no-such-sample", "sample"))).isEmpty();
    }

